  const callOrder: string[] = [];
  const error = new Error('beforeSession failed');
  const hooks: OrchestratorHooks = {
    beforeSession: async () => {
      throw error;
    },
    onError: async () => {
      callOrder.push('onError');
    },
    afterSession: async () => {
      callOrder.push('afterSession');
    },
  };

  const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});

  const call = orchestrator.processMessage(createSession('hello'));
  const outcome = await call.catch(e => e.message);
  expect({outcome, callOrder}).toEqual({
    outcome: 'beforeSession failed',
    callOrder: ['onError', 'afterSession'],
  });
});

